def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced (has matching opening and closing brackets)
    balanced_groups = []
    for group in groups:
        stack = []
        is_balanced = True
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    is_balanced = False
                    break
                stack.pop()
        if is_balanced and not stack:
            balanced_groups.append(group)

    # Step 4: Combine the balanced groups into distinct strings and return them as a list
    distinct_groups = []
    for group in balanced_groups:
        distinct_group = ""
        for char in group:
            if char == "(" or char == ")":
                distinct_group += char
        distinct_groups.append(distinct_group)

    return distinct_groups

