def contains_more_than_three_digits(file_name):
    return sum(1 for char in file_name if char.isdigit()) > 3

def contains_precisely_one_dot(file_name):
    return file_name.count('.') == 1

def part_before_dot_valid(file_name):
    parts = file_name.split('.')
    if len(parts) != 2:
        return False
    before_dot = parts[0]
    return before_dot and before_dot[0].isalpha()

def part_after_dot_valid(file_name):
    parts = file_name.split('.')
    if len(parts) != 2:
        return False
