def count_distinct_characters(string: str) -> int:
    """ Determine the number of unique characters in a given string, treating letters case-insensitively.
    The function should consider uppercase and lowercase versions of the same letter as identical.
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
